function(container, apiUrl, tables) {
  let systemData = tables[0]?.records || [];

  // KPI計算と表示
  function updateKPIs(data) {
    const total = data.length;
    const active = data.filter(r => r.status === '稼働中' || r.status === 'active').length;
    const attention = data.filter(r => r.status === 'メンテナンス' || r.status === '障害' || r.status === 'maintenance' || r.status === 'error').length;

    // 今月のデータ（created_atまたはupdated_atがある場合）
    const now = new Date();
    const thisMonth = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
    const monthlyUpdates = data.filter(r => {
      const date = r.updated_at || r.created_at || r.date;
      return date && date.startsWith(thisMonth);
    }).length;

    container.querySelector('#kpi-total-systems').textContent = total;
    container.querySelector('#kpi-active-systems').textContent = active;
    container.querySelector('#kpi-attention-systems').textContent = attention;
    container.querySelector('#kpi-monthly-updates').textContent = monthlyUpdates;

    const activeRate = total > 0 ? Math.round((active / total) * 100) : 0;
    container.querySelector('#kpi-active-rate').textContent = `稼働率: ${activeRate}%`;

    container.querySelector('#kpi-total-change').textContent = `+${monthlyUpdates} (今月)`;
  }

  // ステータス別円グラフ
  function createStatusChart(data) {
    const statusCounts = {};
    data.forEach(r => {
      const status = r.status || '不明';
      statusCounts[status] = (statusCounts[status] || 0) + 1;
    });

    const ctx = container.querySelector('#status-chart').getContext('2d');
    new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: Object.keys(statusCounts),
        datasets: [{
          data: Object.values(statusCounts),
          backgroundColor: ['#22c55e', '#ef4444', '#f59e0b', '#8b5cf6', '#06b6d4'],
          borderWidth: 2,
          borderColor: '#ffffff'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom',
            labels: {
              color: '#64748b',
              padding: 15,
              usePointStyle: true
            }
          }
        }
      }
    });
  }

  // 月別登録数の棒グラフ
  function createMonthlyChart(data) {
    const monthlyCounts = {};

    // 過去6ヶ月のデータを集計
    for (let i = 5; i >= 0; i--) {
      const date = new Date();
      date.setMonth(date.getMonth() - i);
      const monthKey = date.getFullYear() + '-' + String(date.getMonth() + 1).padStart(2, '0');
      monthlyCounts[monthKey] = 0;
    }

    data.forEach(r => {
      const date = r.created_at || r.updated_at || r.date;
      if (date) {
        const monthKey = date.slice(0, 7);
        if (monthlyCounts.hasOwnProperty(monthKey)) {
          monthlyCounts[monthKey]++;
        }
      }
    });

    const ctx = container.querySelector('#monthly-chart').getContext('2d');
    new Chart(ctx, {
      type: 'bar',
      data: {
        labels: Object.keys(monthlyCounts).map(m => {
          const [year, month] = m.split('-');
          return `${year}/${month}`;
        }),
        datasets: [{
          label: 'システム数',
          data: Object.values(monthlyCounts),
          backgroundColor: '#3b82f6',
          borderColor: '#2563eb',
          borderWidth: 1
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: false
          }
        },
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              color: '#64748b'
            },
            grid: {
              color: '#e2e8f0'
            }
          },
          x: {
            ticks: {
              color: '#64748b'
            },
            grid: {
              color: '#e2e8f0'
            }
          }
        }
      }
    });
  }

  // 要対応項目の表示
  function updateAttentionList(data) {
    const attentionItems = data.filter(r => 
      r.status === 'メンテナンス' || r.status === '障害' || 
      r.status === 'maintenance' || r.status === 'error'
    );

    const listContainer = container.querySelector('#attention-list');

    if (attentionItems.length === 0) {
      listContainer.innerHTML = `
        <div style="text-align: center; padding: 40px; color: var(--text-muted);">
          <div style="font-size: 48px; margin-bottom: 8px;">✓</div>
          <div>現在、要対応項目はありません</div>
        </div>
      `;
      return;
    }

    listContainer.innerHTML = attentionItems.slice(0, 5).map(item => `
      <div style="border-left: 3px solid #ef4444; background: var(--bg-card); padding: 12px; margin-bottom: 8px; border-radius: 4px;">
        <div style="display: flex; justify-content: space-between; align-items: center;">
          <div>
            <div style="color: var(--text); font-weight: 500; margin-bottom: 4px;">${item.name || item.system_name || 'システム名不明'}</div>
            <div style="color: var(--text-muted); font-size: 12px;">状態: ${item.status}</div>
          </div>
          <button class="action-btn secondary" onclick="window.showScreen('scr-3')" style="font-size: 12px; padding: 4px 8px;">詳細</button>
        </div>
      </div>
    `).join('');
  }

  // 最新更新の表示
  function updateRecentUpdates(data) {
    const sortedData = [...data].sort((a, b) => {
      const dateA = a.updated_at || a.created_at || a.date || '1970-01-01';
      const dateB = b.updated_at || b.created_at || b.date || '1970-01-01';
      return dateB.localeCompare(dateA);
    });

    const recentContainer = container.querySelector('#recent-updates');
    const recentItems = sortedData.slice(0, 5);

    if (recentItems.length === 0) {
      recentContainer.innerHTML = `
        <div style="text-align: center; padding: 40px; color: var(--text-muted);">
          <div style="font-size: 48px; margin-bottom: 8px;">📝</div>
          <div>更新履歴がありません</div>
        </div>
      `;
      return;
    }

    recentContainer.innerHTML = recentItems.map(item => {
      const date = item.updated_at || item.created_at || item.date || '';
      const displayDate = date ? new Date(date).toLocaleDateString('ja-JP') : '日付不明';

      return `
        <div style="padding: 8px 0; border-bottom: 1px solid var(--border);">
          <div style="color: var(--text); font-size: 14px; margin-bottom: 2px;">${item.name || item.system_name || 'システム名不明'}</div>
          <div style="color: var(--text-muted); font-size: 12px;">${displayDate}</div>
        </div>
      `;
    }).join('');
  }

  // 初期データの読み込みと表示
  async function loadDashboard() {
    try {
      const data = await window.aivicApi.list(0);
      if (data) {
        systemData = data;
      }

      updateKPIs(systemData);
      createStatusChart(systemData);
      createMonthlyChart(systemData);
      updateAttentionList(systemData);
      updateRecentUpdates(systemData);

    } catch (error) {
      console.error('ダッシュボードデータの読み込みに失敗:', error);
      // 初期データで表示
      updateKPIs(systemData);
      createStatusChart(systemData);
      createMonthlyChart(systemData);
      updateAttentionList(systemData);
      updateRecentUpdates(systemData);
    }
  }

  // 初期化実行
  loadDashboard();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#data-tbody");
  const resultCount = container.querySelector("#result-count");
  const noDataMessage = container.querySelector("#no-data-message");

  let currentData = [];

  // ステータスバッジのスタイル取得
  function getStatusBadge(status) {
    const styles = {
      '稼働中': 'background: #22c55e; color: #ffffff;',
      '停止中': 'background: #ef4444; color: #ffffff;',
      'メンテナンス': 'background: #f59e0b; color: #ffffff;',
      '開発中': 'background: #3b82f6; color: #ffffff;'
    };
    const style = styles[status] || 'background: #6b7280; color: #ffffff;';
    return `<span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500; ${style}">${status || '不明'}</span>`;
  }

  // 1. テーブル再描画関数を定義
  function renderRows(rows) {
    currentData = rows;
    resultCount.textContent = rows.length;

    if (rows.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.classList.remove('hidden');
      return;
    }

    noDataMessage.classList.add('hidden');
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" style="cursor: pointer;">
        <td style="color: var(--text); font-weight: 500;">${r.name || ''}</td>
        <td>${getStatusBadge(r.status)}</td>
        <td style="color: var(--text);">${r.category || ''}</td>
        <td style="color: var(--text);">${r.owner || ''}</td>
        <td style="color: var(--text-muted); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${r.description || ''}</td>
        <td style="color: var(--text-muted); font-size: 14px;">${r.updatedAt ? new Date(r.updatedAt).toLocaleDateString('ja-JP') : ''}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.id}" style="margin-right: 8px;">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 並び替え関数
  function sortData(data, sortType) {
    const sorted = [...data];
    switch (sortType) {
      case 'name-asc':
        return sorted.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      case 'name-desc':
        return sorted.sort((a, b) => (b.name || '').localeCompare(a.name || ''));
      case 'status-asc':
        return sorted.sort((a, b) => (a.status || '').localeCompare(b.status || ''));
      case 'updated-desc':
        return sorted.sort((a, b) => new Date(b.updatedAt || 0) - new Date(a.updatedAt || 0));
      case 'updated-asc':
        return sorted.sort((a, b) => new Date(a.updatedAt || 0) - new Date(b.updatedAt || 0));
      default:
        return sorted;
    }
  }

  // フィルタリング関数
  function filterData(data) {
    const systemName = container.querySelector("#input-system-name").value.toLowerCase();
    const status = container.querySelector("#select-status").value;
    const category = container.querySelector("#select-category").value;
    const owner = container.querySelector("#input-owner").value.toLowerCase();

    return data.filter(row => {
      const matchName = !systemName || (row.name || '').toLowerCase().includes(systemName);
      const matchStatus = !status || row.status === status;
      const matchCategory = !category || row.category === category;
      const matchOwner = !owner || (row.owner || '').toLowerCase().includes(owner);

      return matchName && matchStatus && matchCategory && matchOwner;
    });
  }

  // 2. 初期データを即座に描画
  renderRows(tables[0]?.records || []);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    try {
      const allData = await window.aivicApi.list(0);
      if (allData) {
        const filtered = filterData(allData);
        const sortType = container.querySelector("#select-sort").value;
        const sorted = sortData(filtered, sortType);
        renderRows(sorted);
      }
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#input-system-name").value = '';
    container.querySelector("#select-status").value = '';
    container.querySelector("#select-category").value = '';
    container.querySelector("#input-owner").value = '';
    container.querySelector("#select-sort").value = 'name-asc';

    // 全データを再表示
    window.aivicApi.list(0).then(data => {
      if (data) {
        renderRows(sortData(data, 'name-asc'));
      }
    });
  });

  // 並び替え変更
  container.querySelector("#select-sort").addEventListener("change", () => {
    const sortType = container.querySelector("#select-sort").value;
    const sorted = sortData(currentData, sortType);
    renderRows(sorted);
  });

  // CSVエクスポート
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    try {
      const allData = await window.aivicApi.list(0);
      if (allData) {
        const headers = ['システム名', 'ステータス', 'カテゴリ', '担当者', '説明', '最終更新日'];
        const csvContent = '\uFEFF' + [
          headers.join(','),
          ...allData.map(row => [
            `"${(row.name || '').replace(/"/g, '""')}"`,
            `"${(row.status || '').replace(/"/g, '""')}"`,
            `"${(row.category || '').replace(/"/g, '""')}"`,
            `"${(row.owner || '').replace(/"/g, '""')}"`,
            `"${(row.description || '').replace(/"/g, '""')}"`,
            `"${row.updatedAt ? new Date(row.updatedAt).toLocaleDateString('ja-JP') : ''}"`
          ].join(','))
        ].join('\n');

        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `対象システムデータ一覧_${new Date().toISOString().slice(0, 10)}.csv`;
        link.click();
      }
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
    }
  });

  // ナビゲーションボタン
  container.querySelector("#btn-dashboard").addEventListener("click", () => {
    window.showScreen("scr-1");
  });

  container.querySelector("#btn-settings").addEventListener("click", () => {
    window.showScreen("scr-4");
  });

  // 5. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このシステムデータを削除しますか？")) return;

      try {
        await window.aivicApi.delete(0, deleteBtn.dataset.id);
        const updatedData = await window.aivicApi.list(0);
        if (updatedData) {
          const filtered = filterData(updatedData);
          const sortType = container.querySelector("#select-sort").value;
          const sorted = sortData(filtered, sortType);
          renderRows(sorted);
        }
      } catch (error) {
        console.error('削除エラー:', error);
      }
      return;
    }

    // 詳細ボタン
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-3");
      return;
    }

    // 行クリック（詳細画面へ遷移）
    const row = e.target.closest("tr[data-id]");
    if (row && !e.target.closest("button")) {
      window.showScreen("scr-3");
    }
  });
}

function(container, apiUrl, tables) {
  let currentSystemId = null;
  let originalData = {};

  // URLパラメータからシステムIDを取得
  const urlParams = new URLSearchParams(window.location.search);
  currentSystemId = urlParams.get('id');

  // ステータスバッジの更新
  function updateStatusBadge(status) {
    const badge = container.querySelector('#status-badge');
    const statusMap = {
      'active': { text: '稼働中', bg: '#e8f5e8', color: '#1a2a40' },
      'maintenance': { text: 'メンテナンス中', bg: '#fff3cd', color: '#1a2a40' },
      'stopped': { text: '停止中', bg: '#f8d7da', color: '#1a2a40' },
      'development': { text: '開発中', bg: '#d1ecf1', color: '#1a2a40' }
    };
    const statusInfo = statusMap[status] || statusMap['active'];
    badge.textContent = statusInfo.text;
    badge.style.background = statusInfo.bg;
    badge.style.color = statusInfo.color;
  }

  // フォームにデータを設定
  function populateForm(data) {
    container.querySelector('#input-system-name').value = data.systemName || '';
    container.querySelector('#input-system-code').value = data.systemCode || '';
    container.querySelector('#select-status').value = data.status || 'active';
    container.querySelector('#select-priority').value = data.priority || 'medium';
    container.querySelector('#textarea-description').value = data.description || '';
    container.querySelector('#select-platform').value = data.platform || '';
    container.querySelector('#input-language').value = data.language || '';
    container.querySelector('#input-database').value = data.database || '';
    container.querySelector('#input-server').value = data.server || '';
    container.querySelector('#input-start-date').value = data.startDate || '';
    container.querySelector('#input-maintenance-date').value = data.maintenanceDate || '';
    container.querySelector('#input-owner').value = data.owner || '';
    container.querySelector('#input-contact').value = data.contact || '';
    container.querySelector('#textarea-memo').value = data.memo || '';

    // システム情報の更新
    container.querySelector('#info-created').textContent = data.createdAt ? new Date(data.createdAt).toLocaleString() : '-';
    container.querySelector('#info-updated').textContent = data.updatedAt ? new Date(data.updatedAt).toLocaleString() : '-';
    container.querySelector('#info-id').textContent = data.id || '-';
    container.querySelector('#last-check').textContent = new Date().toLocaleString();

    updateStatusBadge(data.status);
    originalData = { ...data };
  }

  // フォームからデータを取得
  function getFormData() {
    return {
      systemName: container.querySelector('#input-system-name').value,
      systemCode: container.querySelector('#input-system-code').value,
      status: container.querySelector('#select-status').value,
      priority: container.querySelector('#select-priority').value,
      description: container.querySelector('#textarea-description').value,
      platform: container.querySelector('#select-platform').value,
      language: container.querySelector('#input-language').value,
      database: container.querySelector('#input-database').value,
      server: container.querySelector('#input-server').value,
      startDate: container.querySelector('#input-start-date').value,
      maintenanceDate: container.querySelector('#input-maintenance-date').value,
      owner: container.querySelector('#input-owner').value,
      contact: container.querySelector('#input-contact').value,
      memo: container.querySelector('#textarea-memo').value
    };
  }

  // 初期データの読み込み
  async function loadSystemData() {
    if (currentSystemId) {
      // 既存システムの編集
      const systems = await window.aivicApi.list(0);
      if (systems) {
        const system = systems.find(s => s.id == currentSystemId);
        if (system) {
          populateForm(system);
        }
      }
    } else {
      // 新規作成の場合
      const defaultData = {
        status: 'development',
        priority: 'medium',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };
      populateForm(defaultData);
    }
  }

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-2');
  });

  // ナビゲーションボタン
  container.querySelector('#btn-dashboard').addEventListener('click', () => {
    window.showScreen('scr-1');
  });

  container.querySelector('#btn-data-list').addEventListener('click', () => {
    window.showScreen('scr-2');
  });

  container.querySelector('#btn-settings').addEventListener('click', () => {
    window.showScreen('scr-4');
  });

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', () => {
    const formData = getFormData();

    // バリデーション
    if (!formData.systemName.trim()) {
      alert('システム名は必須です。');
      return;
    }
    if (!formData.systemCode.trim()) {
      alert('システムコードは必須です。');
      return;
    }

    // 保存確認モーダルを表示
    container.querySelector('#save-modal').classList.remove('hidden');
  });

  // 保存確認モーダルのイベント
  container.querySelector('#btn-cancel-save').addEventListener('click', () => {
    container.querySelector('#save-modal').classList.add('hidden');
  });

  container.querySelector('#btn-confirm-save').addEventListener('click', async () => {
    container.querySelector('#save-modal').classList.add('hidden');

    const formData = getFormData();
    formData.updatedAt = new Date().toISOString();

    let result;
    if (currentSystemId) {
      // 更新
      result = await window.aivicApi.update(0, currentSystemId, formData);
    } else {
      // 新規作成
      formData.createdAt = new Date().toISOString();
      result = await window.aivicApi.save(0, formData);
    }

    if (result) {
      alert('保存しました。');
      if (!currentSystemId) {
        // 新規作成の場合は一覧画面に戻る
        window.showScreen('scr-2');
      } else {
        // 更新の場合は現在の画面を再読み込み
        loadSystemData();
      }
    }
  });

  // ステータス変更時のバッジ更新
  container.querySelector('#select-status').addEventListener('change', (e) => {
    updateStatusBadge(e.target.value);
  });

  // 初期データ読み込み
  loadSystemData();
}

function(container, apiUrl, tables) {
