  // 8. CSVエクスポートボタン
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ["設定種別", "設定名", "設定値", "更新日時", "更新者"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        r.settingType || "",
        r.settingName || "",
        r.settingValue || "",
        r.updatedAt || "",
        r.updatedBy || ""
      ].map(field => `"${field}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "system_settings.csv";
    link.click();
  });

  // 9. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この設定を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
      return;
    }

    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      alert("編集機能は詳細・編集画面で実装されています");
      window.showScreen('scr-3');
      return;
    }
  });

  // 10. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) renderRows(rows);
  });
}
